-- Initial data model. Apply migrations only after backup and review.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), national_id varchar(32) NOT NULL UNIQUE, email text UNIQUE, phone text UNIQUE, password_hash text NOT NULL, role text NOT NULL DEFAULT 'applicant', created_at timestamptz NOT NULL DEFAULT now(), CHECK(email IS NOT NULL OR phone IS NOT NULL));
CREATE TABLE IF NOT EXISTS applicant_profiles (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, full_name text NOT NULL, birth_date date, city text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS specializations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name_ar text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS educations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), applicant_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, degree_level integer NOT NULL, specialization_id uuid NOT NULL REFERENCES specializations(id), institution text NOT NULL, graduated_on date);
CREATE TABLE IF NOT EXISTS experiences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), applicant_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, employer text NOT NULL, job_title text NOT NULL, field text NOT NULL, started_on date NOT NULL, ended_on date, CHECK(ended_on IS NULL OR ended_on>=started_on));
CREATE TABLE IF NOT EXISTS licenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), applicant_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, license_type text NOT NULL, expires_on date NOT NULL);
CREATE TABLE IF NOT EXISTS jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, department text NOT NULL, description text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','closed')), opens_at timestamptz, closes_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS job_requirements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, kind text NOT NULL, mandatory boolean NOT NULL DEFAULT true, config jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES jobs(id), applicant_id uuid NOT NULL REFERENCES users(id), status text NOT NULL DEFAULT 'submitted', snapshot jsonb NOT NULL, eligibility_result jsonb NOT NULL, submitted_at timestamptz NOT NULL DEFAULT now(), UNIQUE(job_id,applicant_id));
CREATE TABLE IF NOT EXISTS documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), applicant_id uuid NOT NULL REFERENCES users(id), application_id uuid REFERENCES applications(id), object_key text NOT NULL, file_name text NOT NULL, mime_type text NOT NULL, verification_status text NOT NULL DEFAULT 'pending', uploaded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id bigserial PRIMARY KEY, actor_id uuid REFERENCES users(id), action text NOT NULL, entity_type text NOT NULL, entity_id uuid, details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS applications_job_idx ON applications(job_id,status);
CREATE INDEX IF NOT EXISTS experiences_applicant_idx ON experiences(applicant_id);
